// JavaScript / Run Once for All Items. No external packages.
const TZ = 'Asia/Damascus';
const s = v => String(v ?? '').trim();
const clean = v => s(v).replace(/[\r\n\t<>]/g, ' ').slice(0, 80);
function number(v, label) {
  let t = s(v).replace(/[٠-٩]/g, c => String(c.charCodeAt(0)-1632))
    .replace(/[۰-۹]/g, c => String(c.charCodeAt(0)-1776))
    .replace(/٫/g, '.').replace(/٬/g, ',');
  // Commas are thousands separators only: 1,500.25. Reject ambiguous 1,5.
  if (!/^[+-]?(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?$/.test(t))
    throw new Error(`قيمة رقمية مفقودة أو غير صالحة: ${label}`);
  const n = Number(t.replace(/,/g, ''));
  if (!Number.isFinite(n) || Math.abs(n) > 1e12)
    throw new Error(`قيمة خارج النطاق: ${label}`);
  return n;
}
const tidy = n => Math.round((n + Number.EPSILON) * 1e8) / 1e8;
const sum = (rows, fn) => tidy(rows.reduce((a,r) => a+fn(r),0));
const fmt = n => n.toLocaleString('en-US', {maximumFractionDigits: 4});
function localDay(d) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
    timeZone: TZ, year:'numeric', month:'2-digit', day:'2-digit'
  }).formatToParts(d).map(x=>[x.type,x.value]));
  return `${parts.year}-${parts.month}-${parts.day}`;
}
function dateKey(v) {
  const t=s(v);
  // ISO dates only. Datetimes without an offset are interpreted as Damascus local time.
  const m=t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{1,2})(?::(\d{1,2})(?:\.\d{1,9})?)?\s*(Z|[+-]\d{2}:\d{2})?)?$/);
  if (!m) throw new Error('صيغة تاريخ غير صالحة؛ استخدم YYYY-MM-DD أو ISO.');
  const p=x=>String(x).padStart(2,'0');
  const base=`${m[1]}-${p(m[2])}-${p(m[3])}`;
  const check=new Date(`${base}T00:00:00Z`);
  if (!Number.isFinite(check.getTime()) || check.toISOString().slice(0,10)!==base ||
      Number(m[4]||0)>23 || Number(m[5]||0)>59 || Number(m[6]||0)>59)
    throw new Error('تاريخ أو وقت غير صالح في السجلات.');
  if (!m[7]) return base;
  const d=new Date(`${base}T${p(m[4]||0)}:${p(m[5]||0)}:${p(m[6]||0)}${m[7]}`);
  if (!Number.isFinite(d.getTime())) throw new Error('توقيت ISO غير صالح.');
  return localDay(d);
}
const today=localDay(new Date());
const thisMonth=today.slice(0,7);
function rows(items, idField) {
  const seen=new Set();
  return items.map(i=>i.json).filter(r=>r && Object.entries(r)
    .some(([k,v])=>k!=='row_number' && s(v)!=='')).map(r=>{
      const id=s(r[idField]);
      if (id && seen.has(id)) throw new Error(`معرّف مكرر في السجلات: ${clean(id)}`);
      if(id) seen.add(id);
      return r;
    });
}
function salesRows(items) {
  return rows(items,'sale_id').map(r=>{
    const qty=number(r.qty,'كمية البيع'), total=number(r.total,'إجمالي البيع');
    const status=s(r.status).toLowerCase();
    if(qty<=0 || total<0 || !s(r.product) || !['paid','debt'].includes(status))
      throw new Error('سجل بيع بكمية أو صنف أو حالة دفع غير صالحة.');
    if(status==='debt' && !s(r.customer_id)) throw new Error('يوجد بيع بالدين دون معرّف عميل.');
    if(s(r.sale_price)!=='') {
      const expected=tidy(qty*number(r.sale_price,'سعر البيع'));
      if(Math.abs(expected-total)>0.000001) throw new Error('إجمالي بيع لا يطابق الكمية × السعر.');
    }
    return {...r, date:dateKey(r.date), qty,total,status,
      customer_id:s(r.customer_id), invoice_id:s(r.invoice_id), product:s(r.product)};
  });
}
function paymentRows(items) {
  return rows(items,'payment_id').map(r=>{
    const amount=number(r.amount,'مبلغ السداد');
    if(amount<=0 || !s(r.customer_id)) throw new Error('دفعة غير موجبة أو دون معرّف عميل.');
    return {...r,date:dateKey(r.date),amount,customer_id:s(r.customer_id)};
  });
}
function stats(rows) {
  const total=sum(rows,r=>r.total);
  const complete=rows.every(r=>s(r.cost_price)!=='');
  let cost=null;
  if(complete) cost=sum(rows,r=>{
    const n=number(r.cost_price,'سعر التكلفة');
    if(n<0) throw new Error('سعر تكلفة سالب.');
    return r.qty*n;
  });
  return {total,cash:sum(rows.filter(r=>r.status==='paid'),r=>r.total),
    debt:sum(rows.filter(r=>r.status==='debt'),r=>r.total),cost,
    profit:cost===null?null:tidy(total-cost),
    invoices: rows.every(r=>r.invoice_id) ? new Set(rows.map(r=>r.invoice_id)).size : null};
}
function ranking(rows, ascending=false) {
  const map=new Map();
  for(const r of rows) {
    // Keep distinct units separate if an optional unit column is present.
    const key=JSON.stringify([r.product,s(r.unit)]);
    const e=map.get(key)||{name:r.product,unit:s(r.unit),qty:0};
    e.qty=tidy(e.qty+r.qty);map.set(key,e);
  }
  return [...map.values()].sort((a,b)=>(ascending?a.qty-b.qty:b.qty-a.qty)||a.name.localeCompare(b.name,'ar'));
}
const productList = list => list.slice(0,5).map((r,i)=>`${i+1}. ${clean(r.name)}: ${fmt(r.qty)}${r.unit?' '+clean(r.unit):''}`).join('\n') || 'لا توجد مبيعات في الفترة.';
const profitLine = a => a.profit===null ? 'مجمل الربح: غير متاح؛ أسعار تكلفة ناقصة.' : `مجمل الربح قبل المصروفات: ${fmt(a.profit)}`;
const invoiceLine = a => `عدد الفواتير: ${a.invoices===null?'غير متاح؛ معرّفات فواتير ناقصة':fmt(a.invoices)}`;

const cb=$('Telegram Trigger').first().json.callback_query;
if(!cb?.message?.chat?.id) throw new Error('Expected a Telegram dashboard callback with chat id.');
const chatId=cb.message.chat.id;
const key=s(cb.data);
let text;
try {
  const sales=salesRows($('Get Sales for Dashboard').all());
  const payments=paymentRows($input.all()); // Direct input MUST be Payments rows.
  const history=sales.filter(r=>r.date<=today);
  const period=history.filter(r=>r.date.slice(0,7)===thisMonth);
  switch(key) {
    case 'month_sales': {
      const a=stats(period);
      text=`📊 مبيعات الشهر حتى ${today}\n\nالإجمالي: ${fmt(a.total)}\n💵 نقداً: ${fmt(a.cash)}\n🧾 بالدين: ${fmt(a.debt)}\n${invoiceLine(a)}\n\n⭐ أكثر 5 أصناف بالكمية:\n${productList(ranking(period))}`;
      break;
    }
    case 'daily_sales': {
      // Last ten calendar days, including days without sales.
      const dates=Array.from({length:10},(_,i)=>{
        const d=new Date(`${today}T12:00:00Z`);d.setUTCDate(d.getUTCDate()-i);return d.toISOString().slice(0,10);
      });
      const totals=new Map();
      for(const r of history) totals.set(r.date,tidy((totals.get(r.date)||0)+r.total));
      text=`📅 مبيعات آخر 10 أيام تقويمية\n\n${dates.map(d=>`${d} → ${fmt(totals.get(d)||0)}`).join('\n')}\n\nالصفر يعني عدم وجود مبيعات مسجلة.`;
      break;
    }
    case 'capital': {
      const a=stats(period);
      text=`📦 تكلفة البضاعة المباعة — ${thisMonth}\n\n${a.cost===null?'غير متاحة؛ أسعار تكلفة ناقصة.':fmt(a.cost)}\n\nقيمة المخزون الحالية تحتاج كميات المخزون وأسعار تكلفتها من جدول المنتجات.`;
      break;
    }
    case 'month_profit': {
      const a=stats(period);
      text=`💰 ربح الشهر حتى ${today}\n\nالمبيعات: ${fmt(a.total)}\nتكلفة البضاعة المباعة: ${a.cost===null?'غير متاحة':fmt(a.cost)}\n${profitLine(a)}`;
      break;
    }
    case 'debts': {
      const balances=new Map();
      function entry(r) {
        const id=r.customer_id;
        if(!balances.has(id)) balances.set(id,{id,name:clean(r.customer)||id,amount:0});
        return balances.get(id);
      }
      for(const r of history.filter(r=>r.status==='debt')) entry(r).amount+=r.total;
      for(const r of payments.filter(r=>r.date<=today)) entry(r).amount-=r.amount;
      const all=[...balances.values()].map(r=>({...r,amount:tidy(r.amount)}));
      const debtors=all.filter(r=>r.amount>0).sort((a,b)=>b.amount-a.amount||a.id.localeCompare(b.id));
      const negative=all.filter(r=>r.amount<0);
      text=`🧾 الديون المتبقية حتى ${today}\n\nالإجمالي: ${fmt(sum(debtors,r=>r.amount))}\nعدد المدينين: ${debtors.length}\n\nأعلى 5 ديون:\n${debtors.slice(0,5).map((r,i)=>`${i+1}. ${r.name} (${clean(r.id)}): ${fmt(r.amount)}`).join('\n')||'لا توجد ديون موجبة.'}`;
      if(negative.length) text+=`\n\n⚠️ يوجد ${negative.length} حساب برصيد سالب يحتاج مراجعة؛ لم يُخصم من ديون بقية العملاء.`;
      break;
    }
    case 'least_item':
      text=`📉 أقل 5 أصناف بالكمية — ${thisMonth}\n\n${productList(ranking(period,true))}\n\nبين الأصناف التي بيعت فقط؛ لا يشمل أصناف صفر مبيعات.`;
      break;
    default: text='⚠️ استعلام غير معروف. افتح قائمة التقارير مجدداً.';
  }
  const future=sales.filter(r=>r.date>today).length+payments.filter(r=>r.date>today).length;
  if(future) text+='\n\n⚠️ توجد سجلات بتاريخ مستقبلي لم تدخل في التقرير.';
} catch(error) {
  text=`⚠️ تعذّر حساب التقرير بدقة.\n${clean(error.message)}\nراجع البيانات وأعد المحاولة.`;
}
return [{json:{text,chatId}}];

